package android.graphics; import java.awt.*;import java.awt.geom.*;import java.awt.image.BufferedImage;import java.util.ArrayDeque;public class Canvas {public final java.util.ArrayList<float[]> drawnCircles=new java.util.ArrayList<>();public final java.util.ArrayList<String> drawnTexts=new java.util.ArrayList<>();public static final class TextDraw {public final String text;public final float x,y,size;public final int color;TextDraw(String t,float xx,float yy,Paint p){text=t;x=xx;y=yy;size=p.size;color=p.color;}}public final java.util.ArrayList<TextDraw> textDraws=new java.util.ArrayList<>();private Graphics2D g;private final ArrayDeque<Graphics2D> stack=new ArrayDeque<>();public Canvas(BufferedImage image){g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);}public void save(){stack.push(g);g=(Graphics2D)g.create();}public void restore(){g.dispose();g=stack.pop();}public void translate(float x,float y){g.translate(x,y);}public void scale(float x,float y){g.scale(x,y);}public void clipPath(Path path){g.clip(path.shape);}public void clipRect(RectF r){g.clip(new Rectangle2D.Float(r.left,r.top,r.width(),r.height()));}private void paint(Paint p){g.setColor(new java.awt.Color(p.color,true));g.setStroke(new BasicStroke(p.stroke));g.setFont(p.font());}public void drawColor(int color){g.setColor(new java.awt.Color(color,true));g.fillRect(0,0,5000,5000);}public void drawText(String s,float x,float y,Paint p){drawnTexts.add(s);textDraws.add(new TextDraw(s,x,y,p));paint(p);g.drawString(s,x,y);}public void drawCircle(float x,float y,float radius,Paint p){drawnCircles.add(new float[]{x,y,radius});paint(p);Shape s=new Ellipse2D.Float(x-radius,y-radius,2*radius,2*radius);if(p.style==Paint.Style.FILL)g.fill(s);else g.draw(s);}public void drawLine(float x,float y,float x2,float y2,Paint p){paint(p);g.draw(new Line2D.Float(x,y,x2,y2));}public void drawRoundRect(RectF r,float a,float b,Paint p){paint(p);Shape s=new RoundRectangle2D.Float(r.left,r.top,r.width(),r.height(),a*2,b*2);if(p.style==Paint.Style.FILL)g.fill(s);else g.draw(s);}public void drawBitmap(Bitmap b,Object src,RectF dst,Paint p){g.drawImage(b.pixels,(int)dst.left,(int)dst.top,(int)dst.right,(int)dst.bottom,0,0,b.getWidth(),b.getHeight(),null);}}
